def migrar_reservas_legadas(apps, schema_editor):
    """Aloca o bloqueio legado aos pedidos pendentes identificáveis.

    O bloqueio da Fase 1 era um agregado sem identidade. Pedidos pendentes
    provam a intenção de reserva; o que não puder ser atribuído a um pedido
    é liberado ao final (a soma das reservas ativas passa a ser a verdade).
    """
    Estoque = apps.get_model("stock", "Estoque")
    Reserva = apps.get_model("stock", "ReservaEstoque")
    Pedido = apps.get_model("sales", "Pedido")
    ItemPedido = apps.get_model("sales", "ItemPedido")

    estoques = {
        (estoque.produto_id, estoque.unidade_id): estoque
        for estoque in Estoque.objects.all()
    }
    restante = {
        chave: Decimal(estoque.quantidade_bloqueada)
        for chave, estoque in estoques.items()
    }

    pedidos = Pedido.objects.filter(
        status__in=("aguardando_pagamento", "pagamento_pendente"),
        status_financeiro="pendente",
    ).order_by("criado_em", "pk")

    for pedido in pedidos.iterator():
        agregados = {}
        itens = ItemPedido.objects.filter(pedido_id=pedido.pk).order_by("pk")
        for item in itens.iterator():
            chave = (item.produto_id, pedido.unidade_id)
            disponivel_bloqueio = restante.get(chave, Decimal("0.00"))
            if disponivel_bloqueio <= 0:
                continue
            quantidade = min(Decimal(item.quantidade), disponivel_bloqueio)
            if quantidade <= 0:
                continue
            dados = agregados.setdefault(
                chave, {"quantidade": Decimal("0.00"), "item": item}
            )
            dados["quantidade"] += quantidade
            restante[chave] = disponivel_bloqueio - quantidade

        for (produto_id, unidade_id), dados in agregados.items():
            Reserva.objects.create(
                pedido_id=pedido.pk,
                item_pedido_id=dados["item"].pk,
                produto_id=produto_id,
                unidade_id=unidade_id,
                quantidade=dados["quantidade"],
                status="ativa",
            )

    # Sem identidade de pedido, o bloqueio remanescente não pode ser provado.
    for chave, estoque in estoques.items():
        alocado = Decimal(estoque.quantidade_bloqueada) - restante[chave]
        if alocado != estoque.quantidade_bloqueada:
            Estoque.objects.filter(pk=estoque.pk).update(
                quantidade_bloqueada=alocado
            )


